import{setupMobileMenu,initializePageLanguage}from"../global/global.min.js";function initSignupPage(){const e=document.querySelector(".signup-box");e&&e.addEventListener("submit",handleSignup),document.body.classList.add("signup-page")}async function handleSignup(e){e.preventDefault();const n=document.getElementById("email").value,a=document.getElementById("password").value,t=document.getElementById("username").value;if(n&&a&&t)try{const e=window.APP_CONFIG?.api?.baseURL||"http://localhost:8080",i=await fetch(`${e}/api/users/register`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:t,email:n,password:a})}),o=await i.json();i.ok?alert(o.message):alert(o.message||o.error||"Signup failed.")}catch(e){console.error("Error during signup:",e),alert("An error occurred during signup. Please try again.")}else alert("Please fill in all fields")}document.addEventListener("DOMContentLoaded",function(){initSignupPage(),setupMobileMenu(),initializePageLanguage()});